SELECT COALESCE(SUM(GREATEST(0,a.round_no-(SELECT COUNT(*) FROM approval_submission_round r
 WHERE r.tenant_id=a.tenant_id AND r.application_id=a.id AND r.definition_version=a.definition_version)
)),0) FROM approval_application a WHERE a.tenant_id=#{argument1} AND a.process_key=#{argument2} AND a.definition_version=#{argument3} AND a.status<>'DRAFT'
